int archive_read_zip_cleanup(struct archive_read *a) {
  struct zip *zip = (struct zip *)(a->format->data);

  if (zip == NULL)
    return ARCHIVE_OK;

  /* Free resources for different compression streams */
  if (zip->zstrm != NULL) {
    if (zip->zstrm->zalloc)
      free(zip->zstrm->opaque);
    free(zip->zstrm);
  }

  if (zip->lzma_strm != NULL) {
    lzma_end(zip->lzma_strm);
    free(zip->lzma_strm);
  }

  if (zip->bz2_strm != NULL) {
    BZ2_bzDecompressEnd(zip->bz2_strm);
    free(zip->bz2_strm);
  }

  /* Free all ZIP entries */
  struct zip_entry *entry = zip->entries;
  while (entry != NULL) {
    struct zip_entry *next = entry->next;
    if (entry->filename)
      free(entry->filename);
    if (entry->data)
      free(entry->data);
    free(entry);
    entry = next;
  }

  /* Free the main ZIP structure and set format data to NULL */
  free(zip);
  a->format->data = NULL;

  return ARCHIVE_OK;
}

int zip_cleanup(struct archive_read *a) {
    struct zip *zip = (struct zip *)a->format->data;

    if (zip->zlib_stream != NULL) {
        inflateEnd(zip->zlib_stream);
        free(zip->zlib_stream);
        zip->zlib_stream = NULL;
    }

    if (zip->lzma_stream != NULL) {
        lzma_stream_encoder_mem_free(zip->lzma_stream);
        free(zip->lzma_stream);
        zip->lzma_stream = NULL;
    }

    if (zip->bzip2_stream != NULL) {
        BZ2_bzDecompressEnd(zip->bzip2_stream);
        free(zip->bzip2_stream);
        zip->bzip2_stream = NULL;
    }

    struct zip_entry *entry, *next;
    for (entry = zip->entries; entry != NULL; entry = next) {
        next = entry->next;
        free(entry->filename);
        free(entry);
    }

    free(zip->central_dir);
    free(zip);
    a->format->data = NULL;

    return ARCHIVE_OK;
}

int cleanup_zip_archive_read(struct archive_read *a) {
    struct zip *zip = (struct zip *)a->format->data;

    // Free zlib compression stream if valid
    if (zip->zlib_stream != NULL) {
        inflateEnd(zip->zlib_stream);
        free(zip->zlib_stream);
        zip->zlib_stream = NULL;
    }

    // Free BZ2 compression stream if valid
    if (zip->bzip2_stream != NULL) {
        BZ2_bzDecomppressEnd(zip->bzip2_stream);
        free(zip->bzip2_stream);
        zip->bzip2_stream = NULL;
    }

    // Free LZMA compression stream if valid
    if (zip->lzma_stream != NULL) {
        lzma_stream_end(zip->lzma_stream);
        free(zip->lzma_stream);
        zip->lzma_stream = NULL;
    }

    // Free buffers
    if (zip->buffer != NULL) {
        free(zip->buffer);
        zip->buffer = NULL;
    }

    // Free each ZIP entry and its resources
    struct zip_entry *current = zip->entries;
    while (current != NULL) {
        struct zip_entry *next = current->next;

        if (current->entry_data != NULL) {
            free(current->entry_data);
        }
        free(current);
        current = next;
    }

    // Free the main ZIP structure
    free(zip);

    a->format->data = NULL;
    return ARCHIVE_OK;
}

int cleanup_zip_archive_read(struct archive_read *a) {
  struct zip *zip = (struct zip *)a->format->data;

  if (zip->zlib_stream != NULL) {
    inflateEnd(zip->zlib_stream);
    free(zip->zlib_stream);
    zip->zlib_stream = NULL;
  }

  if (zip->lzma_stream != NULL) {
    lzma_stream_encoder_memfree(zip->lzma_stream);
    free(zip->lzma_stream);
    zip->lzma_stream = NULL;
  }

  if (zip->bzip2_stream != NULL) {
    BZ2_bzDecompressEnd(zip->bzip2_stream);
    free(zip->bzip2_stream);
    zip->bzip2_stream = NULL;
  }

  struct zip_entry *entry, *tmp;
  LIST_FOREACH_SAFE(entry, &zip->entries, list, tmp) {
    LIST_REMOVE(entry, list);
    free(entry->data);
    free(entry);
  }

  free(zip->central_directory);
  free(zip);
  a->format->data = NULL;

  return ARCHIVE_OK;
}

int archive_read_support_zip_cleanup(struct archive_read *a) {
  struct zip *zip = (struct zip *)a->format_data;

  if (zip == NULL)
    return (ARCHIVE_OK);

  if (zip->dstream != NULL)
    free(zip->dstream);
  if (zip->entry != NULL) {
    struct zip_entry *entry, *next;
    for (entry = zip->entry; entry != NULL; entry = next) {
      next = entry->next;
      if (entry->filename != NULL)
        free(entry->filename);
      if (entry->extra != NULL)
        free(entry->extra);
      if (entry->comment != NULL)
        free(entry->comment);
      free(entry);
    }
  }

  if (zip->central_dir != NULL)
    free(zip->central_dir);
  if (zip->local_dir != NULL)
    free(zip->local_dir);
  if (zip->file != NULL)
    free(zip->file);

  free(zip);
  a->format_data = NULL;

  return (ARCHIVE_OK);
}
